using System;using System.Collections;using System.Collections.Generic;using System.IO;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [UnityTest] public IEnumerator R16ReviewRepair(){Directory.CreateDirectory(Evidence);string file=Path.Combine(Evidence,"review-repair.json");Assert.That(File.Exists(file),Is.False);var report=new R16Report{revision="r16-review-repair",method="3affected natural launch/contact cases after independent review; no input probes or ready-pose suite. Exact actor/state spin and retry request telemetry checked. No fun/adoption/full C7 verdict."};Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(report,true));save();
 foreach(var spec in new[]{new R12Spec{id="standard12",angle=12,level=0,rate=2},new R12Spec{id="floor16",angle=16,level=0,rate=2},new R12Spec{id="fast35",angle=35}}){yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(spec.angle,spec.level,spec.rate,1);var sim=Property(current,"ReviewSimulation");var body=(Rigidbody)Property(sim,"Body");var row=new R16Trial{id=spec.id,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt")),launchBodySpin=body.angularVelocity.magnitude/(Mathf.PI*2),launchBudget=Convert.ToSingle(Property(sim,"RotorCapacity"))};report.trials.Add(row);
 for(int i=0;i<11000&&!(bool)Property(current,"Finished");i++)Call(current,"Tick",1f/60);row.final=JsonUtility.ToJson(State(current));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.actualBreaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});row.spent=Convert.ToSingle(Property(sim,"OverdriveSpent"));save();Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);Assert.That(F(State(current),"bodySpinRps"),Is.EqualTo(Convert.ToSingle(Property(sim,"SpinRps"))));float requested=F(State(current),"requestedSpinRps");Assert.That(requested,Is.GreaterThan(0));CaptureRoute(spec.id,"result");Call(current,"RetryLaunch","");Assert.That(F(State(current),"requestedSpinRps"),Is.EqualTo(requested));Assert.That(Convert.ToInt32(Field(State(current),"destructionEvent")),Is.EqualTo(0));Assert.That(Field(State(current),"resultOverview"),Is.Null);Call(current,"Prepare","");row.prepareClean=F(State(current),"bodySpinRps")==0&&F(State(current),"requestedSpinRps")==0&&F(State(current),"time")==0;Assert.That(row.prepareClean,Is.True);save();Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED_NO_OBSERVED_FAULT";save();}
}
